    ("'इंडिका' नामक पुस्तक के लेखक कौन हैं?", "चाणक्य", "मेगास्थनीज", "फाहियान", "ह्वेनसांग", 1, "मेगास्थनीज सेल्युकस निकेटर का राजदूत था, जो चंद्रगुप्त मौर्य के दरबार में आया और 'इंडिका' लिखी।", "आसान"),
    ("कलिंग का भीषण युद्ध किस वर्ष लड़ा गया था?", "261 ई.पू.", "326 ई.पू.", "273 ई.पू.", "185 ई.पू.", 0, "सम्राट अशोक ने अपने राज्याभिषेक के 8वें वर्ष (261 ईसा पूर्व) में कलिंग (ओडिशा) पर आक्रमण किया था।", "आसान"),
    ("कलिंग युद्ध के नरसंहार के बाद अशोक ने किस बौद्ध भिक्षु से बौद्ध धर्म की दीक्षा ली?", "उपरूपी", "उपगुप्त", "नागार्जुन", "आनंद", 1, "अशोक ने बौद्ध भिक्षु उपगुप्त से बौद्ध धर्म की दीक्षा ग्रहण की और भेरीघोष की जगह धम्मघोष अपनाया।", "आसान"),
    ("अशोक के शिलालेखों को सर्वप्रथम 1837 में किसने पढ़ा था?", "अलेक्जेंडर कनिंघम", "जेम्स प्रिंसेप", "विलियम जोन्स", "मैक्स मूलर", 1, "अंग्रेज विद्वान जेम्स प्रिंसेप ने 1837 में सर्वप्रथम अशोक की ब्राह्मी लिपि को पढ़ने में सफलता पाई।", "आसान"),
    ("सांची के स्तूप (मध्य प्रदेश) का निर्माण किसने करवाया था?", "चंद्रगुप्त मौर्य", "सम्राट अशोक", "कनिष्क", "हर्षवर्धन", 1, "सांची के प्रसिद्ध बौद्ध स्तूप का निर्माण सम्राट अशोक ने करवाया था।", "आसान"),
    ("मौर्य वंश का अंतिम शासक कौन था जिसकी हत्या पुष्यमित्र शुंग ने की?", "कुणाल", "दशरथ", "बृहद्रथ", "संप्रति", 2, "मौर्य वंश का अंतिम सम्राट बृहद्रथ था, जिसकी हत्या उसके सेनापति पुष्यमित्र शुंग ने 185 ई.पू. में की।", "मध्यम"),
    ("शुंग वंश की स्थापना किसने की थी?", "पुष्यमित्र शुंग", "अग्निमित्र", "वसुमित्र", "देवभूति", 0, "पुष्यमित्र शुंग ने अंतिम मौर्य राजा बृहद्रथ की हत्या कर शुंग वंश की नींव रखी।", "मध्यम"),
    ("चरक किस प्रसिद्ध कुषाण शासक के राजवैद्य थे?", "चंद्रगुप्त मौर्य", "कनिष्क", "अशोक", "हर्षवर्धन", 1, "महर्षि चरक कुषाण सम्राट कनिष्क के राजवैद्य थे। उन्होंने 'चरक संहिता' की रचना की।", "आसान"),
    ("भारत का राष्ट्रीय पंचांग किस संवत पर आधारित है?", "विक्रम संवत", "शक संवत (78 ई.)", "गुप्त संवत", "हिजरी संवत", 1, "भारत का राष्ट्रीय कैलेंडर शक संवत पर आधारित है, जिसे कनिष्क ने 78 ईस्वी में शुरू किया था।", "आसान"),
    ("गुप्त वंश का संस्थापक कौन था?", "चंद्रगुप्त प्रथम", "श्रीगुप्त", "समुद्रगुप्त", "स्कंदगुप्त", 1, "गुप्त साम्राज्य की स्थापना श्रीगुप्त ने लगभग 240 ईस्वी में की थी।", "मध्यम"),
    ("भारतीय इतिहास में किस गुप्त शासक को 'भारत का नेपोलियन' कहा जाता है?", "चंद्रगुप्त प्रथम", "समुद्रगुप्त", "चंद्रगुप्त विक्रमादित्य", "स्कंदगुप्त", 1, "इतिहासकार वी.ए. स्मिथ ने समुद्रगुप्त की अपराजित विजयों के कारण उसे 'भारत का नेपोलियन' कहा।", "आसान"),
    ("प्रयाग प्रशस्ति (इलाहाबाद स्तंभ लेख) की रचना किसने की थी?", "कालिदास", "हरिषेण", "बाणभट्ट", "दंडी", 1, "समुद्रगुप्त के दरबारी कवि हरिषेण ने प्रयाग प्रशस्ति की रचना संस्कृत भाषा में की।", "आसान"),
    ("'विक्रमादित्य' की उपाधि किस गुप्त शासक ने धारण की थी?", "चंद्रगुप्त प्रथम", "समुद्रगुप्त", "चंद्रगुप्त द्वितीय", "कुमारगुप्त", 2, "शकों को पराजित करने के उपलक्ष्य में चंद्रगुप्त द्वितीय ने 'विक्रमादित्य' की उपाधि धारण की।", "आसान"),
    ("चीनी यात्री फाहियान किस शासक के शासनकाल में भारत आया था?", "हर्षवर्धन", "चंद्रगुप्त द्वितीय (विक्रमादित्य)", "कनिष्क", "समुद्रगुप्त", 1, "फाहियान 399 ईस्वी में गुप्त सम्राट चंद्रगुप्त द्वितीय के शासनकाल में भारत आया था।", "आसान"),
    ("नालंदा विश्वविद्यालय की स्थापना किस गुप्त शासक ने की थी?", "समुद्रगुप्त", "कुमारगुप्त प्रथम", "स्कंदगुप्त", "विष्णुगुप्त", 1, "बिहार में विश्वप्रसिद्ध नालंदा विश्वविद्यालय की स्थापना कुमारगुप्त प्रथम (महेंद्रादित्य) ने की थी।", "आसान"),
    ("हूणों के आक्रमण से भारत की रक्षा करने वाला गुप्त शासक कौन था?", "स्कंदगुप्त", "समुद्रगुप्त", "चंद्रगुप्त द्वितीय", "कुमारगुप्त", 0, "स्कंदगुप्त ने बर्बर हूणों को बुरी तरह पराजित कर भारत की रक्षा की थी। जूनागढ़ अभिलेख इसका प्रमाण है।", "मध्यम"),
    ("भारत का शेक्सपियर किसे कहा जाता है?", "तुलसीदास", "कालिदास", "बाणभट्ट", "भवभूति", 1, "चंद्रगुप्त द्वितीय के नवरत्नों में शामिल महाकवि कालिदास को 'भारत का शेक्सपियर' कहा जाता है।", "आसान"),
    ("'अभिज्ञानशाकुंतलम' और 'मेघदूतम' किसकी रचनाएं हैं?", "भवभूति", "कालिदास", "विशाखदत्त", "भारवि", 1, "महाकवि कालिदास ने अभिज्ञानशाकुंतलम, मालविकाग्निमित्रम, रघुवंशम और मेघदूतम की रचना की।", "आसान"),
    ("शून्य (0) और दशमलव प्रणाली का आविष्कार किस काल में हुआ?", "वैदिक काल", "मौर्य काल", "गुप्त काल", "कुषाण काल", 2, "गुप्त काल में महान खगोलशास्त्री आर्यभट्ट ने शून्य और दशमलव प्रणाली का विकास किया।", "आसान"),
    ("'सूर्य सिद्धांत' और 'आर्यभटीय' के लेखक कौन हैं?", "वराहमिहिर", "आर्यभट्ट", "ब्रह्मगुप्त", "भास्कराचार्य", 1, "महान गणितज्ञ एवं खगोलविद् आर्यभट्ट ने आर्यभटीय और सूर्य सिद्धांत की रचना की।", "आसान"),
    ("हर्षवर्धन की राजधानी कहाँ थी?", "उज्जैन", "पाटलिपुत्र", "कन्नौज", "थानेश्वर", 2, "हर्षवर्धन ने अपनी राजधानी थानेश्वर से कन्नौज स्थानांतरित की थी।", "आसान"),
